-- 取回 sorted
WITH "base" AS (SELECT "ds_orders"."Row ID" AS "f_row_id", "ds_orders"."Order ID" AS "f_order_id", "ds_orders"."Order Date" AS "f_order_date", "ds_orders"."Ship Date" AS "f_ship_date", "ds_orders"."Ship Mode" AS "f_ship_mode", "ds_orders"."Customer ID" AS "f_customer_id", "ds_orders"."Customer Name" AS "f_customer_name", "ds_orders"."Segment" AS "f_segment", "ds_orders"."Country/Region" AS "f_country_region", "ds_orders"."City" AS "f_city", "ds_orders"."State/Province" AS "f_state_province", "ds_orders"."Postal Code" AS "f_postal_code", "ds_orders"."Region" AS "f_region", "ds_orders"."Product ID" AS "f_product_id", "ds_orders"."Category" AS "f_category", "ds_orders"."Sub-Category" AS "f_sub_category", "ds_orders"."Product Name" AS "f_product_name", "ds_orders"."Sales" AS "f_sales", "ds_orders"."Quantity" AS "f_quantity", "ds_orders"."Discount" AS "f_discount", "ds_orders"."Profit" AS "f_profit" FROM "SALES"."ds_orders" "ds_orders"), "src" AS (SELECT * FROM "base" WHERE ("f_country_region" IN ('United States'))), "lod" AS (SELECT "f_sub_category" AS "__d0", "f_order_id" AS "__d1", SUM("f_profit") AS "__v" FROM "src" GROUP BY "f_sub_category", "f_order_id"), "dimf_ext" AS (SELECT "r".*, "l0"."__v" AS "__lod_0" FROM "src" "r" LEFT JOIN "lod" "l0" ON "r"."f_sub_category" IS NOT DISTINCT FROM "l0"."__d0" AND "r"."f_order_id" IS NOT DISTINCT FROM "l0"."__d1"), "agg" AS (SELECT "f_sub_category" AS "__k0", SUM("f_profit") AS "__a0" FROM "dimf_ext" GROUP BY "f_sub_category"), "combos" AS (SELECT DISTINCT "f_sub_category" AS "__g0", "f_order_id" AS "__g1", "__lod_0" FROM "dimf_ext"), "combo_agg" AS (SELECT "__g0" AS "__k0", AVG("__lod_0") AS "__a1" FROM "combos" GROUP BY "__g0"), "agg_1" AS (SELECT "b".*, "c0"."__a1" FROM "agg" "b" LEFT JOIN "combo_agg" "c0" ON "b"."__k0" IS NOT DISTINCT FROM "c0"."__k0"), "meas" AS (SELECT "agg_1".*, "__a0" AS "__m0", ("__a1") AS "__m2" FROM "agg_1"), "sort_agg" AS (SELECT "f_sub_category" AS "__k0", SUM("f_profit") AS "__a0" FROM "dimf_ext" GROUP BY "f_sub_category"), "sort" AS (SELECT "__k0" AS "__key", "__a0" AS "__v" FROM "sort_agg"), "sorted" AS (SELECT "m".*, "s0"."__v" AS "__sort0" FROM "meas" "m" LEFT JOIN "sort" "s0" ON "s0"."__key" IS NOT DISTINCT FROM "m"."__k0") SELECT * FROM "sorted"
